const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>','check-square':'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="m8 12 2.5 2.5L16 9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',timer:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.5 1.5M9 2h6M12 2v3"/>',chart:'<path d="M4 19V5M4 19h17"/><path d="m7 15 4-4 3 2 6-7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.8 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.8-1l-1.7.7-1.4-2.4 1.4-1.1a7 7 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.8-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.8 1l1.7-.7 1.4 2.4-1.4 1.1a7 7 0 0 1 0 2Z" transform="translate(-1 -1) scale(1.08)"/>',shield:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/>',search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>','chevron-down':'<path d="m7 10 5 5 5-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',book:'<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v17H6.5A2.5 2.5 0 0 0 4 22z"/><path d="M4 5.5v14A2.5 2.5 0 0 1 6.5 17H20"/>',edit:'<path d="m15 5 4 4M4 20l4.5-1 10-10a2.8 2.8 0 0 0-4-4l-10 10Z"/><path d="M4 20h16"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6M10 11v6m4-6v6"/>',close:'<path d="m18 6-12 12M6 6l12 12"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',sparkle:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8zM19 16l1 2.5 2.5 1-2.5 1L19 23l-1-2.5-2.5-1 2.5-1z"/>',chevleft:'<path d="m15 18-6-6 6-6"/>',chevright:'<path d="m9 18 6-6-6-6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',volume:'<path d="M11 5 6 9H3v6h3l5 4zM15.5 8.5a5 5 0 0 1 0 7M18 5a9 9 0 0 1 0 14"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.6 9A7 7 0 0 1 18 6l2 2M4 16l2 2a7 7 0 0 0 12.4-3"/>',moon:'<path d="M20.8 13A8.5 8.5 0 0 1 11 3.2 8.5 8.5 0 1 0 20.8 13Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',list:'<path d="M9 6h11M9 12h11M9 18h11M4 6h.01M4 12h.01M4 18h.01"/>',computer:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',flask:'<path d="M9 3h6m-5 0v7l-5.5 9a2 2 0 0 0 1.7 3h11.6a2 2 0 0 0 1.7-3L14 10V3M8 16h8"/>',math:'<path d="M5 4h14M5 12h14M5 20h14M9 2v4m6 4v4m-6 4v4"/>'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const today=new Date();today.setHours(0,0,0,0);const iso=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};const shift=(days)=>{const x=new Date(today);x.setDate(x.getDate()+days);return iso(x)};const dateFrom=(s)=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)};const fmtDate=(s,opt={month:'short',day:'numeric'})=>dateFrom(s).toLocaleDateString('en-US',opt);const weekday=(s,opt={weekday:'long'})=>dateFrom(s).toLocaleDateString('en-US',opt);const id=()=>Math.random().toString(36).slice(2,10);
function emptyState(user=null){return {profile:{name:user?.name||user?.userMetadata?.full_name||user?.email?.split('@')[0]||'',program:''},subjects:[],tasks:[],sessions:[],settings:{focusDuration:25,defaultPriority:'Medium',notifications:true,weeklyGoal:12}}}
let theme=localStorage.getItem('studysync-theme')||'light';document.body.dataset.theme=theme;let currentUser=null,saveQueue=Promise.resolve(),state=emptyState();async function dataRequest(options={}){await refreshSession().catch(()=>null);const send=()=>fetch('/.netlify/functions/data',{credentials:'same-origin',keepalive:(options.body?.length||0)<60000,...options});let response=await send();if(response.status===401&&await refreshSession().catch(()=>null))response=await send();return response}
function save(){if(!currentUser)return saveQueue;const snapshot=JSON.stringify(state);saveQueue=saveQueue.then(async()=>{const response=await dataRequest({method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot});if(!response.ok)throw new Error('save failed')}).catch(()=>toast('Could not save your changes. Check your connection and try again.','error'));return saveQueue}let page=location.hash.slice(1)||'overview',taskFilter='all',taskQuery='',subjectFilter='',priorityFilter='',statusFilter='',sortBy='date',calendarDate=new Date(today),selectedDate=iso(today),calendarView='Month',timerPreset=state.settings?.focusDuration||25,timerRemaining=(state.settings?.focusDuration||25)*60,timerInterval=null,timerRunning=false,sessionSubject=state.subjects?.[0]?.name||'',sessionTask='',settingsTab='Profile',subjectDetail=null;
const pageNames={overview:'Overview',tasks:'My tasks',calendar:'Calendar','focus':'Focus room',progress:'Progress',subjects:'Your courses',settings:'Settings',privacy:'Privacy policy'};const root=document.getElementById('page-content');document.getElementById('footer-year').textContent=new Date().getFullYear();
function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;document.getElementById('toast-region').append(el);setTimeout(()=>el.remove(),3200)}function subjectInfo(name){return state.subjects.find(s=>s.name===name)||{name,color:'#786ce0',code:'',icon:'book'}}function taskSort(a,b){return `${a.date}T${a.time}`.localeCompare(`${b.date}T${b.time}`)}function sortedTasks(tasks=state.tasks){return [...tasks].sort(taskSort)}function dueLabel(t){if(t.date===iso(today))return t.time?`Today, ${time12(t.time)}`:'Today';return `${fmtDate(t.date)}, ${time12(t.time)}`}function time12(t){if(!t)return '';const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}function dateLong(d=today){return d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}function initials(name){return name.split(/\s+/).map(s=>s[0]).join('').slice(0,2).toUpperCase()}
function applyTheme(){document.body.dataset.theme=theme;localStorage.setItem('studysync-theme',theme);const b=document.getElementById('theme-toggle');if(b){const dark=theme==='dark';b.innerHTML=icon(dark?'sun':'moon');b.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');b.title=dark?'Switch to light mode':'Switch to dark mode';b.setAttribute('aria-pressed',String(dark))}}function syncShell(){applyTheme();document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)});document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.getElementById('crumb-page').textContent=pageNames[page]||'Overview';document.getElementById('sidebar-name').textContent=state.profile.name;document.getElementById('sidebar-program').textContent=state.profile.program;document.querySelector('.avatar-top').textContent=initials(state.profile.name);document.querySelector('.avatar-sidebar').textContent=initials(state.profile.name);document.getElementById('nav-task-count').textContent=state.tasks.filter(t=>!t.done).length;const sn=document.getElementById('subject-nav');sn.innerHTML=state.subjects.map(s=>`<a class="nav-link" href="#subjects" data-subject="${s.id}"><span class="course-dot" style="--subject:${s.color}"></span><span>${esc(s.name)}</span></a>`).join('')}
function render(){syncShell();const views={overview:renderOverview,tasks:renderTasks,calendar:renderCalendar,focus:renderFocus,progress:renderProgress,subjects:renderSubjects,settings:renderSettings,privacy:renderPrivacy};root.innerHTML=(views[page]||renderOverview)();bindPage();}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function subjectChip(name){const s=subjectInfo(name);return `<span class="subject-chip" style="--subject:${s.color}">${esc(name)}</span>`}function prio(name){return `<span class="priority ${String(name).toLowerCase()}">${esc(name)}</span>`}function taskRow(t){return `<div class="task-row ${t.done?'done':''}"><input class="task-check" type="checkbox" aria-label="Mark ${esc(t.title)} ${t.done?'incomplete':'complete'}" data-toggle-task="${t.id}" ${t.done?'checked':''}><div class="task-main"><div class="task-title">${esc(t.title)}</div><div class="task-meta">${subjectChip(t.subject)}<span>${t.minutes||25} min</span></div></div><div class="task-trailing"><div class="task-due">${time12(t.time)}</div>${prio(t.priority)}</div></div>`}
function renderOverview(){const unfinished=state.tasks.filter(t=>!t.done);const weekEnd=shift(6);const weekTasks=state.tasks.filter(t=>t.date>=iso(today)&&t.date<=weekEnd);const completed=weekTasks.filter(t=>t.done).length;const rate=weekTasks.length?Math.round(completed/weekTasks.length*100):0;const dueSoon=unfinished.filter(t=>t.date>=iso(today)&&t.date<=shift(1)).length;const todayTasks=sortedTasks(state.tasks.filter(t=>t.date===iso(today))).slice(0,4);const week=Array.from({length:7},(_,i)=>{const d=new Date(today);d.setDate(d.getDate()-((d.getDay()+6)%7)+i);return iso(d)});const vals=week.map(d=>state.sessions.filter(s=>s.date===d).reduce((a,s)=>a+s.minutes,0)/60);const sum=state.sessions.filter(s=>s.date>=iso(today)&&s.date<=weekEnd).reduce((a,s)=>a+s.minutes,0)/60;const max=Math.max(4,...vals);const deadlines=sortedTasks(unfinished.filter(t=>t.date>=iso(today))).slice(0,3);return `<div class="date-strip">${dateLong().toUpperCase()}</div><div class="welcome-row"><div><h2>Good ${today.getHours()<12?'morning':today.getHours()<17?'afternoon':'evening'}, ${esc(state.profile.name.split(' ')[0])}.</h2><p>One clear view of what matters in your studies today.</p></div><div class="week-note">WEEK ${String(Math.ceil((today.getDate()+new Date(today.getFullYear(),today.getMonth(),1).getDay())/7)).padStart(2,'0')} <span>·</span> ${fmtDate(iso(today),{month:'short'}).toUpperCase()}</div></div><section class="stats-grid" aria-label="Study summary"><article class="stat-card"><div class="stat-top"><span class="stat-label">Tasks this week</span><span class="stat-icon" style="--tone:var(--violet);--tint:var(--violet-pale)">${icon('list')}</span></div><div class="stat-value">${weekTasks.length}<small> tasks</small></div><div class="stat-caption">On your plate this week</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Completed</span><span class="stat-icon" style="--tone:var(--green);--tint:var(--green-pale)">${icon('check')}</span></div><div class="stat-value">${completed}<small> / ${weekTasks.length}</small><span class="stat-trend">${rate}%</span></div><div class="stat-caption">Weekly completion rate</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Due soon</span><span class="stat-icon" style="--tone:var(--gold);--tint:var(--gold-pale)">${icon('clock')}</span></div><div class="stat-value">${dueSoon}</div><div class="stat-caption">Due within 48 hours</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Focus time</span><span class="stat-icon" style="--tone:var(--blue);--tint:var(--blue-pale)">${icon('timer')}</span></div><div class="stat-value">${sum.toFixed(sum%1?1:0)}<small> hrs</small></div><div class="stat-caption">Logged this week</div></article></section><div class="dashboard-grid"><div class="column-stack"><section class="panel panel-pad"><div class="panel-heading"><div><h2>Today's tasks</h2><p>A manageable list, one step at a time.</p></div><a class="panel-link" href="#tasks">All tasks ${icon('arrow',13)}</a></div><div class="task-list">${todayTasks.length?todayTasks.map(taskRow).join(''):`<div class="empty-state"><p>Nothing due today. Take a breath or plan ahead.</p></div>`}</div><div class="task-list-footer"><span class="small-muted">${todayTasks.filter(t=>t.done).length} of ${todayTasks.length} done</span><button class="button button-text button-small" data-action="add-task">${icon('plus',14)} Add a task</button></div></section><section class="panel activity-panel"><div class="panel-heading"><div><h2>Study rhythm</h2><p>Focus time across the week, in hours.</p></div><span class="small-muted">${sum.toFixed(sum%1?1:0)} hrs total</span></div><div class="activity-chart"><div class="chart-y"><span>4h</span><span>3h</span><span>2h</span><span>1h</span><span>0</span></div><div class="bars-area">${vals.map((v,i)=>`<div class="bar-col"><div class="bar ${week[i]===iso(today)?'today':''}" style="height:${Math.max(4,v/max*82)}%" title="${v.toFixed(1)} hours"></div><span class="bar-label">${['M','T','W','T','F','S','S'][i]}</span></div>`).join('')}</div></div><div class="chart-legend"><span class="legend-dot"></span> ${today.toLocaleDateString('en-US',{weekday:'long'})} · Today</div></section></div><div class="column-stack"><section class="panel panel-pad"><div class="panel-heading"><div><h2>Coming up</h2><p>Your next few deadlines.</p></div><a href="#calendar" class="panel-link">Calendar</a></div><div class="deadline-list">${deadlines.length?deadlines.map(t=>`<div class="deadline-item"><div class="deadline-date"><b>${dateFrom(t.date).getDate()}</b><span>${dateFrom(t.date).toLocaleDateString('en-US',{month:'short'})}</span></div><div><div class="deadline-title">${esc(t.title)}</div><div class="deadline-sub">${esc(t.subject)}</div></div><div class="deadline-when"><strong>${t.date===iso(today)?'Today':t.date===shift(1)?'Tomorrow':weekday(t.date,{weekday:'short'})}</strong>${time12(t.time)}</div></div>`).join(''):`<p class="small-muted">No upcoming deadlines.</p>`}</div></section><section class="panel activity-panel"><div class="panel-heading"><div><h2>Your week</h2><p>A small check-in on your progress.</p></div></div><div class="insight-card"><span class="insight-spark">${icon('sparkle')}</span><div class="insight-kicker">${weekTasks.length?'Weekly progress':'Getting started'}</div><h3>${weekTasks.length?`${rate}% of this week's tasks are complete.`:'Add a task to track your progress.'}</h3><p>${weekTasks.length?'Each small finish adds up.':'Your study activity will appear here.'}</p><div class="progress-line"><span style="width:${rate}%"></span></div><div class="insight-foot"><span>${completed} of ${weekTasks.length} tasks</span><a class="panel-link" href="#progress">See progress</a></div></div></section></div></div>`}
function renderTasks(){let arr=sortedTasks(state.tasks).filter(t=>{const q=taskQuery.toLowerCase();const matches=!q||`${t.title} ${t.subject} ${t.description}`.toLowerCase().includes(q);const tf=taskFilter==='today'?t.date===iso(today):taskFilter==='upcoming'?t.date>iso(today)&&!t.done:taskFilter==='completed'?t.done:true;return matches&&tf&&(!subjectFilter||t.subject===subjectFilter)&&(!priorityFilter||t.priority===priorityFilter)&&(!statusFilter||(statusFilter==='done'?t.done:!t.done))});if(sortBy==='priority')arr.sort((a,b)=>['High','Medium','Low'].indexOf(a.priority)-['High','Medium','Low'].indexOf(b.priority));const counts={all:state.tasks.length,today:state.tasks.filter(t=>t.date===iso(today)).length,upcoming:state.tasks.filter(t=>t.date>iso(today)&&!t.done).length,completed:state.tasks.filter(t=>t.done).length};return `<div class="page-heading"><div><div class="eyebrow">THE DETAILS, IN ONE PLACE</div><h1>My tasks</h1><p>Keep track of every assignment and deadline.</p></div><div class="heading-actions"><button class="button button-primary" data-action="add-task">${icon('plus')} Add new task</button></div></div><div class="toolbar"><label class="field-control toolbar-search">${icon('search')}<input type="search" id="task-search" placeholder="Find an assignment…" value="${esc(taskQuery)}" aria-label="Search tasks"></label><select class="field-control" id="subject-filter" aria-label="Filter by course"><option value="">All courses</option>${state.subjects.map(s=>`<option ${subjectFilter===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select><select class="field-control" id="priority-filter" aria-label="Filter by priority"><option value="">Any priority</option>${['High','Medium','Low'].map(x=>`<option ${priorityFilter===x?'selected':''}>${x}</option>`).join('')}</select><select class="field-control" id="status-filter" aria-label="Filter by status"><option value="">Any status</option><option value="open" ${statusFilter==='open'?'selected':''}>In progress</option><option value="done" ${statusFilter==='done'?'selected':''}>Completed</option></select><select class="field-control" id="sort-by" aria-label="Sort tasks"><option value="date">Due date</option><option value="priority" ${sortBy==='priority'?'selected':''}>Priority</option></select></div><div class="tabs">${[['all','All tasks'],['today','Today'],['upcoming','Upcoming'],['completed','Completed']].map(([k,label])=>`<button class="tab-button ${taskFilter===k?'selected':''}" data-task-tab="${k}">${label}<span class="tab-count">${counts[k]}</span></button>`).join('')}</div><section class="panel"><div class="task-table"><div class="task-table-head"><span></span><span>Assignment</span><span>Course</span><span>Due</span><span>Priority</span><span></span></div>${arr.length?arr.map(t=>`<div class="manage-row ${t.done?'done':''}"><input class="task-check" type="checkbox" aria-label="Mark ${esc(t.title)} ${t.done?'incomplete':'complete'}" data-toggle-task="${t.id}" ${t.done?'checked':''}><div><div class="manage-title" style="${t.done?'text-decoration:line-through;color:#88918f':''}">${esc(t.title)}</div><div class="manage-sub">${t.description?esc(t.description):`${t.minutes||25} min planned`}</div></div><div class="manage-sub manage-subject">${subjectChip(t.subject)}</div><div class="manage-due">${dueLabel(t)}</div><div class="manage-priority">${prio(t.priority)}</div><div class="row-actions"><button class="icon-button" data-edit-task="${t.id}" aria-label="Edit ${esc(t.title)}">${icon('edit')}</button><button class="icon-button" data-delete-task="${t.id}" aria-label="Delete ${esc(t.title)}">${icon('trash')}</button></div></div>`).join(''):`<div class="empty-state"><div class="empty-state-mark">${icon('check-square',23)}</div><h3>${taskQuery?'No matching tasks':'Nothing in this view'}</h3><p>${taskQuery?'Try a different phrase or clear your filters.':'Tasks you add will show up here.'}</p>${taskQuery?'<button class="button button-secondary button-small" data-action="clear-filters">Clear filters</button>':'<button class="button button-primary button-small" data-action="add-task">Add your first task</button>'}</div>`}</div></section>`}
function renderCalendar(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1),start=new Date(y,m,1-first.getDay()),days=Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d});const selTasks=sortedTasks(state.tasks.filter(t=>t.date===selectedDate));return `<div class="page-heading"><div><div class="eyebrow">MAKE ROOM FOR THE WORK</div><h1>Calendar</h1><p>See what's due, and make a little space to get it done.</p></div><button class="button button-primary" data-action="add-task">${icon('plus')} Add task</button></div><div class="calendar-layout"><section class="panel calendar-panel"><div class="calendar-toolbar"><div class="month-title"><strong>${calendarDate.toLocaleDateString('en-US',{month:'long'})}</strong><span>${y}</span></div><div class="month-controls"><button class="button button-secondary button-small" data-calendar-today>Today</button><button class="icon-button" data-month="-1" aria-label="Previous month">${icon('chevleft')}</button><button class="icon-button" data-month="1" aria-label="Next month">${icon('chevright')}</button></div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${days.map(d=>{const ds=iso(d),items=sortedTasks(state.tasks.filter(t=>t.date===ds));return `<button class="calendar-day ${d.getMonth()!==m?'outside':''} ${ds===iso(today)?'today':''} ${ds===selectedDate?'selected':''}" data-select-date="${ds}" aria-label="${dateLong(d)}, ${items.length} tasks"><span class="day-number">${d.getDate()}</span><span class="day-events">${items.slice(0,2).map(t=>`<span class="day-event ${t.priority==='High'?'high':t.done?'green':''}">${esc(t.title)}</span>`).join('')}${items.length>2?`<span class="day-event">+${items.length-2} more</span>`:''}</span></button>`}).join('')}</div><div class="chart-legend"><span class="legend-dot" style="background:#bd762c"></span> High priority <span class="legend-dot" style="background:#6c62d8;margin-left:8px"></span> Other assignments</div></section><aside class="panel calendar-side"><div class="selected-date-label">SELECTED DAY</div><h3>${dateLong(dateFrom(selectedDate))}</h3><div class="agenda-list">${selTasks.length?selTasks.map(t=>`<div class="agenda-item" style="--agenda:${t.priority==='High'?'#bd762c':subjectInfo(t.subject).color}"><strong>${esc(t.title)}</strong><span>${time12(t.time)} · ${esc(t.subject)} · ${t.done?'Completed':t.priority+' priority'}</span></div>`).join(''):`<div class="agenda-empty">No assignments scheduled for this day. Leave it open or add something.</div>`}</div><button class="button button-secondary agenda-add" data-action="add-task" data-date="${selectedDate}">${icon('plus',14)} Add to this day</button></aside></div>`}
function renderFocus(){const subjectOptions=state.subjects.map(s=>`<option ${sessionSubject===s.name?'selected':''}>${esc(s.name)}</option>`).join('');const tasks=state.tasks.filter(t=>!t.done&&(!sessionSubject||t.subject===sessionSubject));const todaySessions=state.sessions.filter(s=>s.date===iso(today));const mins=todaySessions.reduce((a,s)=>a+s.minutes,0);const count=todaySessions.length;return `<div class="page-heading"><div><div class="eyebrow">A QUIETER KIND OF PRODUCTIVITY</div><h1>Focus room</h1><p>One thing at a time. Give your attention a place to land.</p></div></div><div class="focus-grid"><section class="panel focus-main"><div class="focus-topline"><span class="focus-label">A session for you</span><span class="sound-toggle">Sound <button class="switch" id="sound-toggle" role="switch" aria-checked="false" aria-label="Toggle session sound"></button></span></div><div class="timer-wrap"><div class="timer-ring" id="timer-ring"><div class="timer-center"><div class="timer-time" id="timer-display">${timerText()}</div><div class="timer-caption" id="timer-caption">${timerRunning?'IN FOCUS':'READY WHEN YOU ARE'}</div></div></div></div><div class="timer-controls"><button class="button button-primary" id="timer-start">${timerRunning?'Pause':timerRemaining<(timerPreset*60)?'Resume':'Start focusing'}</button><button class="button button-secondary" id="timer-reset">${icon('refresh',15)} Reset</button></div><div class="timer-presets">${[[25,'Focus'],[5,'Short break'],[15,'Long break']].map(([v,l])=>`<button class="preset ${timerPreset===v?'active':''}" data-preset="${v}">${l} · ${v}m</button>`).join('')}</div><div class="focus-selects"><div class="form-field"><label for="focus-subject">Course</label><select id="focus-subject">${subjectOptions||'<option>No courses yet</option>'}</select></div><div class="form-field"><label for="focus-task">Working on</label><select id="focus-task"><option value="">Choose an assignment</option>${tasks.map(t=>`<option value="${t.id}" ${sessionTask===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select></div></div></section><aside class="focus-aside"><section class="panel focus-summary"><h3>Today's practice</h3><p>Every focused minute counts.</p><div class="focus-metrics"><div class="focus-metric"><strong>${count}</strong><span>Sessions completed</span></div><div class="focus-metric"><strong>${mins}<small> min</small></strong><span>Time in focus</span></div></div></section><section class="panel streak-card"><div class="eyebrow">YOUR STREAK</div><h3>${studyStreak()} days of showing up</h3><p>Consistency is built session by session. Keep it gentle.</p></section><section class="panel session-history"><h3>Recent sessions</h3>${state.sessions.slice().reverse().slice(0,4).map(s=>`<div class="session-row"><strong>${esc(s.subject)} · ${fmtDate(s.date)}</strong><span>${s.minutes} min</span></div>`).join('')||'<p class="small-muted">Your completed sessions will appear here.</p>'}</section></aside></div>`}
function timerText(){return `${String(Math.floor(timerRemaining/60)).padStart(2,'0')}:${String(timerRemaining%60).padStart(2,'0')}`}function studyStreak(){const dates=new Set(state.sessions.map(s=>s.date));let n=0,d=new Date(today);if(!dates.has(iso(d)))d.setDate(d.getDate()-1);while(dates.has(iso(d))&&n<365){n++;d.setDate(d.getDate()-1)}return n}
function renderProgress(){const week=Array.from({length:7},(_,i)=>{const d=new Date(today);d.setDate(d.getDate()-6+i);return iso(d)});const hours=week.map(d=>state.sessions.filter(s=>s.date===d).reduce((a,s)=>a+s.minutes,0)/60);const total=state.sessions.reduce((a,s)=>a+s.minutes,0);const done=state.tasks.filter(t=>t.done).length;const pct=state.tasks.length?Math.round(done/state.tasks.length*100):0;const subjectStats=state.subjects.map(s=>{const ts=state.tasks.filter(t=>t.subject===s.name);return {...s,done:ts.filter(t=>t.done).length,total:ts.length}});const goal=state.settings.weeklyGoal||12;const thisWeek=state.sessions.filter(s=>s.date>=shift(-6)&&s.date<=iso(today)).reduce((a,s)=>a+s.minutes,0)/60;return `<div class="page-heading"><div><div class="eyebrow">NOTICE YOUR OWN RHYTHM</div><h1>Progress</h1><p>A record of your effort, without the grade pressure.</p></div><span class="week-note">UPDATED AS YOU WORK</span></div><div class="progress-stat-grid"><article class="stat-card"><div class="stat-label">Tasks completed</div><div class="stat-value">${done}<small> / ${state.tasks.length}</small></div><div class="stat-caption">Assignments finished</div></article><article class="stat-card"><div class="stat-label">Completion rate</div><div class="stat-value">${pct}<small>%</small></div><div class="stat-caption">Across all your tasks</div></article><article class="stat-card"><div class="stat-label">Focus hours</div><div class="stat-value">${(total/60).toFixed(1)}<small> hrs</small></div><div class="stat-caption">Time intentionally spent</div></article><article class="stat-card"><div class="stat-label">Current streak</div><div class="stat-value">${studyStreak()}<small> days</small></div><div class="stat-caption">One session a day</div></article></div><div class="progress-layout"><div class="column-stack"><section class="panel panel-pad"><div class="panel-heading"><div><h2>Focus time</h2><p>Your last seven days, measured in hours.</p></div><span class="small-muted">${thisWeek.toFixed(1)} hrs this week</span></div><div class="progress-bars">${hours.map((v,i)=>`<div class="progress-bar-group"><i class="${i===6?'alt':''}" style="height:${Math.max(4,v/Math.max(3,...hours)*75)}%" title="${v.toFixed(1)} hours"></i><span>${['M','T','W','T','F','S','S'][week[i]&&((dateFrom(week[i]).getDay()+6)%7)]}</span></div>`).join('')}</div></section><section class="panel panel-pad"><div class="panel-heading"><div><h2>By course</h2><p>Completed assignments in each course.</p></div></div><div class="subject-progress">${subjectStats.map(s=>`<div class="subject-progress-row"><span class="subject-progress-name">${esc(s.name)}</span><div class="progress-line"><span style="width:${s.total?s.done/s.total*100:0}%;background:${s.color}"></span></div><span>${s.done}/${s.total}</span></div>`).join('')}</div></section></div><div class="column-stack"><section class="panel productive-card"><div class="eyebrow">A REALISTIC GOAL</div><h3>${thisWeek.toFixed(1)} of ${goal} hours</h3><p>Your weekly focus goal is ${goal} hours. You're ${thisWeek>=goal?'there — nice work.':`${Math.max(0,goal-thisWeek).toFixed(1)} hours away, at your own pace.`}</p><div class="progress-line" style="margin-top:14px;background:#e1ddcf"><span style="width:${Math.min(100,thisWeek/goal*100)}%;background:#ab7a31"></span></div></section><section class="panel panel-pad"><div class="panel-heading"><div><h2>Recently finished</h2><p>Small steps you took.</p></div><a href="#tasks" class="panel-link">All tasks</a></div><div class="recent-list">${sortedTasks(state.tasks.filter(t=>t.done)).reverse().slice(0,5).map(t=>`<div class="recent-row"><span class="done-mark">${icon('check',12)}</span><div><strong>${esc(t.title)}</strong><span>${esc(t.subject)} · ${fmtDate(t.date)}</span></div></div>`).join('')||'<p class="small-muted">Finished tasks will show here.</p>'}</div></section></div></div>`}
function renderSubjects(){if(subjectDetail){const s=subjectInfo(subjectDetail),tasks=sortedTasks(state.tasks.filter(t=>t.subject===s.name));return `<div class="page-heading"><div><div class="eyebrow">YOUR COURSES</div><h1>${esc(s.name)}</h1><p>${esc(s.code||'Course overview')} · ${tasks.filter(t=>!t.done).length} active assignments</p></div><button class="button button-secondary" data-subject-back>${icon('chevleft',14)} All courses</button></div><section class="panel subject-detail"><div class="panel-pad"><div class="panel-heading"><div class="subject-detail-title"><span class="subject-icon" style="--subject:${s.color}">${icon(s.icon)}</span><div><h2>${esc(s.name)}</h2><p>${esc(s.code||'')}</p></div></div><button class="button button-primary button-small" data-action="add-task" data-subject-name="${esc(s.name)}">${icon('plus',14)} Add assignment</button></div><div class="task-list">${tasks.length?tasks.map(taskRow).join(''):'<div class="empty-state"><h3>No assignments yet</h3><p>Add the first task for this course.</p></div>'}</div></div></section>`}return `<div class="page-heading"><div><div class="eyebrow">THE BIG PICTURE, BY COURSE</div><h1>Your courses</h1><p>Keep assignments grouped by the classes they belong to.</p></div><button class="button button-primary" data-action="add-subject">${icon('plus')} Add course</button></div><div class="subject-grid">${state.subjects.map(s=>{const ts=state.tasks.filter(t=>t.subject===s.name),done=ts.filter(t=>t.done).length,pct=ts.length?done/ts.length*100:0;return `<article class="panel subject-card" style="--subject:${s.color}"><div class="subject-card-head"><span class="subject-icon">${icon(s.icon)}</span><button class="icon-button subject-menu" data-subject-menu="${s.id}" aria-label="Edit ${esc(s.name)}">${icon('more')}</button></div><button class="button-text" style="text-align:left;padding:0;height:auto;min-height:0" data-open-subject="${s.id}"><h3>${esc(s.name)}</h3></button><div class="subject-code">${esc(s.code||'COURSE')}</div><p>${ts.filter(t=>!t.done).length} active · ${done} completed</p><div class="progress-line"><span style="width:${pct}%;background:${s.color}"></span></div><div class="subject-card-foot"><span>${ts.length} assignments</span><button class="button-text button-small" data-open-subject="${s.id}">Open course ${icon('arrow',13)}</button></div></article>`}).join('')}${!state.subjects.length?`<section class="panel empty-state"><h3>Start with a course</h3><p>Courses help keep assignments in context.</p><button class="button button-primary button-small" data-action="add-subject">Add a course</button></section>`:''}</div>`}
function renderSettings(){const tabs=['Profile','Appearance','Study defaults','Notifications','Data'];let content='';if(settingsTab==='Profile')content=`<h2>Your profile</h2><p>Just enough to make this space feel like yours.</p><div class="settings-form"><div class="form-field"><label for="profile-name">Display name</label><input id="profile-name" value="${esc(state.profile.name)}" autocomplete="name"></div><div class="form-field"><label for="profile-program">Program</label><input id="profile-program" value="${esc(state.profile.program)}"></div><div class="form-field full"><button class="button button-primary button-small" id="save-profile">Save profile</button></div></div>`;else if(settingsTab==='Appearance')content=`<h2>Appearance</h2><p>Choose a softer light workspace or a low-glare dark theme.</p><div class="theme-choices"><button class="theme-choice ${theme==='light'?'selected':''}" data-theme-pick="light"><span class="theme-swatch light-swatch"><i></i><i></i><i></i></span><strong>Light</strong><span>Bright paper and sea glass</span></button><button class="theme-choice ${theme==='dark'?'selected':''}" data-theme-pick="dark"><span class="theme-swatch dark-swatch"><i></i><i></i><i></i></span><strong>Dark</strong><span>Deep teal and soft ink</span></button></div>`;else if(settingsTab==='Study defaults')content=`<h2>Study defaults</h2><p>Make the starting point fit the way you work.</p><div class="settings-form"><div class="form-field"><label for="default-priority">Default task priority</label><select id="default-priority">${['Low','Medium','High'].map(x=>`<option ${state.settings.defaultPriority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="focus-default">Default focus duration</label><select id="focus-default">${[15,25,30,45,50].map(x=>`<option value="${x}" ${state.settings.focusDuration===x?'selected':''}>${x} minutes</option>`).join('')}</select></div><div class="form-field"><label for="weekly-goal">Weekly focus goal</label><input type="number" min="1" max="60" id="weekly-goal" value="${state.settings.weeklyGoal}"></div><div class="form-field full"><button class="button button-primary button-small" id="save-study-settings">Save preferences</button></div></div>`;else if(settingsTab==='Notifications')content=`<h2>Notifications</h2><p>Choose whether StudySync can show helpful reminders in this browser.</p><div class="setting-row"><div><strong>Assignment reminders</strong><span>Show a notice for tasks coming up soon.</span></div><button class="switch" id="notifications-switch" role="switch" aria-checked="${state.settings.notifications}" aria-label="Toggle assignment reminders"></button></div><p class="small-muted">Notifications are local to this browser. StudySync does not send emails or push notifications.</p>`;else content=`<h2>Your data</h2><p>Your courses, assignments, and focus sessions are stored in this browser.</p><div class="setting-row"><div><strong>Download a copy</strong><span>Save your StudySync data as a JSON file.</span></div><button class="button button-secondary button-small" id="export-data">Download data</button></div><div class="setting-row"><div><strong>Clear local data</strong><span>Remove courses, tasks, and session history from this browser.</span></div><button class="button button-secondary button-small" id="clear-data">Clear data</button></div>`;return `<div class="page-heading"><div><div class="eyebrow">MAKE IT YOUR OWN</div><h1>Settings</h1><p>Small preferences for a study space that works for you.</p></div></div><div class="settings-layout"><nav class="panel settings-tabs" aria-label="Settings sections">${tabs.map(t=>`<button class="settings-tab ${settingsTab===t?'selected':''}" data-settings-tab="${t}">${t}</button>`).join('')}</nav><section class="panel settings-panel">${content}</section></div>`}
function renderPrivacy(){return `<div class="page-heading"><div><div class="eyebrow">PLAIN LANGUAGE, PLEASE</div><h1>Privacy policy</h1><p>What StudySync stores, and what it doesn't.</p></div></div><article class="privacy-content"><section class="panel"><span class="privacy-updated">LAST UPDATED · OCTOBER 17, 2026</span><h2>Information you add</h2><p>StudySync can store the display name and program you enter, course names and codes, assignment titles, descriptions, due dates, priorities, completion states, and focus session details, and your chosen theme. The application begins with clearly labeled example tasks so you can explore the interface. You can edit or remove this information at any time.</p><h2>How it is stored</h2><p>This version saves information in your browser's local storage on this device. It does not include an account system or a cloud sync service. Anyone who can access this browser profile may be able to access the locally stored StudySync information. Browser settings or private browsing can affect whether data persists.</p><h2>Services and sharing</h2><p>StudySync does not send your study information to a server as part of this implementation. The page loads fonts from Google Fonts; your browser may contact Google's font service to retrieve them. No analytics or advertising service is configured here.</p><h2>Keeping and deleting information</h2><p>Data stays in local storage until you remove it, clear site data in your browser, or use Settings → Data → Clear data. Download a copy from that same section before clearing it if you want to keep a record.</p><h2>Security</h2><p>Local storage is not encrypted by this application. Use a device and browser profile you trust, and avoid entering information you would not want another user of this device to see.</p><h2>Contact</h2><p>Privacy questions: <a href="villalobosangelmaye2911@gmail.com">villalobosangelmaye2911@gmail.com</a> <span class="small-muted"></span></p></section></article>`}
function bindPage(){if(page==='tasks'){const qs=document.getElementById('task-search');qs?.addEventListener('input',e=>{taskQuery=e.target.value;const pos=e.target.selectionStart;render();const n=document.getElementById('task-search');n.focus();n.setSelectionRange(pos,pos)});document.getElementById('subject-filter')?.addEventListener('change',e=>{subjectFilter=e.target.value;render()});document.getElementById('priority-filter')?.addEventListener('change',e=>{priorityFilter=e.target.value;render()});document.getElementById('status-filter')?.addEventListener('change',e=>{statusFilter=e.target.value;render()});document.getElementById('sort-by')?.addEventListener('change',e=>{sortBy=e.target.value;render()})}if(page==='focus'){document.getElementById('timer-start')?.addEventListener('click',toggleTimer);document.getElementById('timer-reset')?.addEventListener('click',resetTimer);document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>setPreset(Number(b.dataset.preset))));document.getElementById('focus-subject')?.addEventListener('change',e=>{sessionSubject=e.target.value;sessionTask='';render()});document.getElementById('focus-task')?.addEventListener('change',e=>sessionTask=e.target.value);document.getElementById('sound-toggle')?.addEventListener('click',e=>{const b=e.currentTarget;b.setAttribute('aria-checked',b.getAttribute('aria-checked')!=='true');toast(`Session sound ${b.getAttribute('aria-checked')==='true'?'on':'off'}.`)})}if(page==='settings'){document.getElementById('save-profile')?.addEventListener('click',()=>{state.profile.name=document.getElementById('profile-name').value.trim()||'Student';state.profile.program=document.getElementById('profile-program').value.trim()||'Student';save();render();toast('Profile saved.','success')});document.getElementById('save-study-settings')?.addEventListener('click',()=>{state.settings.defaultPriority=document.getElementById('default-priority').value;state.settings.focusDuration=Number(document.getElementById('focus-default').value);state.settings.weeklyGoal=Math.max(1,Number(document.getElementById('weekly-goal').value)||12);save();toast('Study preferences saved.','success')});document.getElementById('notifications-switch')?.addEventListener('click',e=>{state.settings.notifications=!state.settings.notifications;save();render()});document.getElementById('export-data')?.addEventListener('click',exportData);document.getElementById('clear-data')?.addEventListener('click',confirmClear)}document.querySelectorAll('[data-page]').forEach(a=>a.addEventListener('click',()=>{if(page==='focus'&&timerRunning){}document.getElementById('sidebar').classList.remove('open')}))}
function toggleTimer(){if(timerRunning){clearInterval(timerInterval);timerRunning=false;render();return}timerRunning=true;timerInterval=setInterval(()=>{timerRemaining--;const el=document.getElementById('timer-display'),ring=document.getElementById('timer-ring'),cap=document.getElementById('timer-caption');if(el)el.textContent=timerText();if(ring)ring.style.setProperty('--timer-pct',`${timerRemaining/(timerPreset*60)*100}%`);if(cap)cap.textContent='IN FOCUS';if(timerRemaining<=0)finishSession()},1000);render()}
function finishSession(){clearInterval(timerInterval);timerRunning=false;const task=state.tasks.find(t=>t.id===sessionTask);const spent=timerPreset;state.sessions.push({id:id(),date:iso(today),subject:sessionSubject,minutes:spent,taskId:sessionTask||null});if(task){task.done=true;toast(`Session saved. “${task.title}” marked complete.`,'success')}else toast('Focus session complete. Nice work.','success');save();timerRemaining=timerPreset*60;render();showModal('Session complete',`<p class="confirmation-copy">You spent ${spent} focused minutes on ${esc(sessionSubject)}${task?` · ${esc(task.title)}`:''}. Take a short break or begin another session.</p><div class="dialog-actions"><button class="button button-secondary" data-close-modal>Close</button><button class="button button-primary" data-break="5">Start a 5 min break</button></div>`)}function resetTimer(){clearInterval(timerInterval);timerRunning=false;timerRemaining=timerPreset*60;render()}function setPreset(n){clearInterval(timerInterval);timerRunning=false;timerPreset=n;timerRemaining=n*60;render()}
function modalShell(title,subtitle,body,footer=''){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" aria-label="Close dialog" data-close-modal>${icon('close')}</button></header>${body}${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.querySelector('[data-close-modal]')?.focus();document.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.matches('[data-backdrop]'))closeModal()});document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',closeModal));}function showModal(title,content){modalShell(title,'',`<div class="modal-body">${content}</div>`)}function escModal(e){if(e.key==='Escape')closeModal()}function closeModal(){document.getElementById('modal-root').innerHTML=''}
function openTaskModal(task=null,defaults={}){const edit=!!task;const d=task||{title:'',description:'',subject:defaults.subject||state.subjects[0]?.name||'',date:defaults.date||iso(today),time:'12:00',priority:state.settings.defaultPriority||'Medium',minutes:25};const body=`<form id="task-form" class="modal-form" novalidate><div class="form-field full" data-field="title"><label for="task-title">Assignment title <span class="required">*</span></label><input id="task-title" name="title" required maxlength="100" placeholder="e.g. Read chapter 5" value="${esc(d.title)}" aria-describedby="task-title-error"><span class="form-error" id="task-title-error">Add a short title for this assignment.</span></div><div class="form-field full"><label for="task-description">Notes <span class="small-muted">(optional)</span></label><textarea id="task-description" name="description" placeholder="What should you remember?">${esc(d.description||'')}</textarea></div><div class="form-field"><label for="task-subject">Course <span class="required">*</span></label><select id="task-subject" name="subject" required>${state.subjects.map(s=>`<option value="${esc(s.name)}" ${d.subject===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}${state.subjects.length?'':'<option value="">Add a course first</option>'}</select></div><div class="form-field" data-field="date"><label for="task-date">Due date <span class="required">*</span></label><input id="task-date" type="date" name="date" required value="${esc(d.date)}"></div><div class="form-field"><label for="task-time">Due time</label><input id="task-time" type="time" name="time" value="${esc(d.time||'12:00')}"></div><div class="form-field"><label for="task-priority">Priority</label><select id="task-priority" name="priority">${['Low','Medium','High'].map(x=>`<option ${d.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="task-minutes">Estimated time</label><select id="task-minutes" name="minutes">${[15,25,30,45,60,90,120].map(x=>`<option value="${x}" ${Number(d.minutes||25)===x?'selected':''}>${x} minutes</option>`).join('')}</select></div><input type="hidden" name="id" value="${edit?d.id:''}"></form>`;modalShell(edit?'Edit assignment':'Add a task',edit?'Update the details whenever plans change.':'Capture the next thing you need to work on.',`<div class="modal-body">${body}</div>`,`<button class="button button-secondary" data-close-modal>Cancel</button><button class="button button-primary" id="save-task">${edit?'Save changes':'Save task'}</button>`);document.getElementById('save-task').addEventListener('click',()=>{const form=document.getElementById('task-form'),title=form.elements.title.value.trim(),date=form.elements.date.value;document.querySelector('[data-field="title"]').classList.toggle('invalid',!title);document.querySelector('[data-field="date"]').classList.toggle('invalid',!date);if(!title||!date){(!title?form.elements.title:form.elements.date).focus();return}const t={id:form.elements.id.value||id(),title,description:form.elements.description.value.trim(),subject:form.elements.subject.value,date,time:form.elements.time.value,priority:form.elements.priority.value,minutes:Number(form.elements.minutes.value),done:task?.done||false};if(edit)state.tasks=state.tasks.map(x=>x.id===task.id?t:x);else state.tasks.push(t);save();closeModal();render();toast(edit?'Assignment updated.':'Task added.','success')})}
function openSubjectModal(subject=null){const edit=!!subject,oldName=subject?.name;const colors=['#786ce0','#bd762c','#238f91','#4d926e','#c66c61','#567fc2'];const body=`<form id="subject-form" class="modal-form" novalidate><div class="form-field full" data-field="subject-name"><label for="subject-name">Course name <span class="required">*</span></label><input id="subject-name" maxlength="50" value="${esc(subject?.name||'')}" placeholder="e.g. Introduction to Psychology"><span class="form-error">Enter a course name.</span></div><div class="form-field"><label for="subject-code">Course code</label><input id="subject-code" maxlength="20" value="${esc(subject?.code||'')}" placeholder="e.g. PSY 101"></div><div class="form-field"><label for="subject-color">Course color</label><select id="subject-color">${colors.map(c=>`<option value="${c}" ${subject?.color===c?'selected':''}>${c===colors[0]?'Violet':c===colors[1]?'Ochre':c===colors[2]?'Sea glass':c===colors[3]?'Sage':c===colors[4]?'Terracotta':'Blue'}</option>`).join('')}</select></div></form>`;modalShell(edit?'Edit course':'Add a course','Courses make it easier to see how your work fits together.',`<div class="modal-body">${body}</div>`,`<button class="button button-secondary" data-close-modal>Cancel</button><button class="button button-primary" id="save-subject">${edit?'Save changes':'Add course'}</button>`);document.getElementById('save-subject').addEventListener('click',()=>{const name=document.getElementById('subject-name').value.trim();document.querySelector('[data-field="subject-name"]').classList.toggle('invalid',!name);if(!name){document.getElementById('subject-name').focus();return}if(state.subjects.some(s=>s.name.toLowerCase()===name.toLowerCase()&&s.id!==subject?.id)){toast('A course with that name already exists.');return}if(edit){subject.name=name;subject.code=document.getElementById('subject-code').value.trim();subject.color=document.getElementById('subject-color').value;state.tasks.forEach(t=>{if(t.subject===oldName)t.subject=name})}else state.subjects.push({id:id(),name,code:document.getElementById('subject-code').value.trim(),color:document.getElementById('subject-color').value,icon:'book'});save();closeModal();render();toast(edit?'Course updated.':'Course added.','success')})}
function deleteTask(taskId){const t=state.tasks.find(x=>x.id===taskId);if(!t)return;modalShell('Delete this assignment?','This will remove it from your task list.',`<div class="modal-body"><p class="confirmation-copy"><strong>${esc(t.title)}</strong> will be deleted. This action cannot be undone.</p></div>`,`<button class="button button-secondary" data-close-modal>Keep assignment</button><button class="button danger-button" id="confirm-delete">Delete assignment</button>`);document.getElementById('confirm-delete').addEventListener('click',()=>{state.tasks=state.tasks.filter(x=>x.id!==taskId);save();closeModal();render();toast('Assignment deleted.')})}
function confirmClear(){modalShell('Clear all StudySync data?','This permanently removes your profile, courses, tasks, and focus sessions from your account.',`<div class="modal-body"><p class="confirmation-copy">Your profile, courses, tasks, and focus sessions will be deleted from your StudySync account. Download a copy first if you want to keep it.</p></div>`,`<button class="button button-secondary" data-close-modal>Cancel</button><button class="button danger-button" id="confirm-clear">Clear all data</button>`);document.getElementById('confirm-clear').addEventListener('click',()=>{localStorage.removeItem('studysync-state');state=emptyState(currentUser);save();closeModal();render();toast('Study data cleared.')})}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='studysync-data.json';a.click();URL.revokeObjectURL(url);toast('Your data download has started.','success')}
function bindGlobal(){document.addEventListener('click',e=>{if(e.target.closest('[data-logout]')){clearInterval(timerInterval);timerRunning=false;saveQueue.then(()=>logout()).catch(()=>{}).finally(()=>{currentUser=null;state=emptyState();showAuth('You are signed out.')});return}const themeChoice=e.target.closest('[data-theme-pick]');if(themeChoice){theme=themeChoice.dataset.themePick;applyTheme();render();return}if(e.target.closest('#theme-toggle')){theme=theme==='dark'?'light':'dark';applyTheme();return}const toggle=e.target.closest('[data-toggle-task]');if(toggle){const t=state.tasks.find(x=>x.id===toggle.dataset.toggleTask);if(t){t.done=toggle.checked;save();render();toast(t.done?'Nice work — task completed.':'Task moved back to in progress.',t.done?'success':'')}return}const add=e.target.closest('[data-action="add-task"]');if(add){openTaskModal(null,{date:add.dataset.date||selectedDate,subject:add.dataset.subjectName||''});return}if(e.target.closest('[data-action="add-subject"]')||e.target.closest('#add-subject')){openSubjectModal();return}const edit=e.target.closest('[data-edit-task]');if(edit){openTaskModal(state.tasks.find(t=>t.id===edit.dataset.editTask));return}const del=e.target.closest('[data-delete-task]');if(del){deleteTask(del.dataset.deleteTask);return}const tab=e.target.closest('[data-task-tab]');if(tab){taskFilter=tab.dataset.taskTab;render();return}if(e.target.closest('[data-action="clear-filters"]')){taskQuery='';subjectFilter='';priorityFilter='';statusFilter='';render();return}const mon=e.target.closest('[data-month]');if(mon){calendarDate.setMonth(calendarDate.getMonth()+Number(mon.dataset.month));render();return}if(e.target.closest('[data-calendar-today]')){calendarDate=new Date(today);selectedDate=iso(today);render();return}const sd=e.target.closest('[data-select-date]');if(sd){selectedDate=sd.dataset.selectDate;render();return}const st=e.target.closest('[data-settings-tab]');if(st){settingsTab=st.dataset.settingsTab;render();return}const op=e.target.closest('[data-open-subject]');if(op){subjectDetail=state.subjects.find(s=>s.id===op.dataset.openSubject)?.name||null;render();return}if(e.target.closest('[data-subject-back]')){subjectDetail=null;render();return}const sm=e.target.closest('[data-subject-menu]');if(sm){const s=state.subjects.find(x=>x.id===sm.dataset.subjectMenu);if(s)subjectMenu(s);return}const go=e.target.closest('[data-goto]');if(go){location.hash=go.dataset.goto;return}const br=e.target.closest('[data-break]');if(br){closeModal();setPreset(Number(br.dataset.break));return}if(e.target.closest('[data-close-modal]'))closeModal()});document.getElementById('menu-toggle').addEventListener('click',e=>{const nav=document.getElementById('sidebar'),open=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});document.getElementById('global-search').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.value.trim()){taskQuery=e.target.value.trim();location.hash='tasks'}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.modal-backdrop'))closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('global-search').focus()}});document.getElementById('notifications').addEventListener('click',()=>{const n=state.tasks.filter(t=>!t.done&&t.date>=iso(today)&&t.date<=shift(1)).length;toast(n?`You have ${n} assignment${n===1?'':'s'} due in the next 48 hours.`:'No urgent deadlines. You’re all caught up.','success')});window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview',previous=page;if(page==='focus'&&next!=='focus'&&timerRunning){}page=next;if(next!=='subjects'||previous!=='subjects')subjectDetail=null;render();window.scrollTo(0,0)})}
function subjectMenu(s){modalShell(esc(s.name),'Course options',`<div class="modal-body"><p class="confirmation-copy">${esc(s.code||'Course')} · ${state.tasks.filter(t=>t.subject===s.name).length} assignments</p><div class="dialog-actions" style="justify-content:flex-start"><button class="button button-secondary" id="edit-subject">${icon('edit',14)} Edit course</button><button class="button button-secondary" id="delete-subject">${icon('trash',14)} Delete course</button></div></div>`);document.getElementById('edit-subject').addEventListener('click',()=>{closeModal();openSubjectModal(s)});document.getElementById('delete-subject').addEventListener('click',()=>{closeModal();modalShell('Delete this course?','Assignments in this course will also be removed.',`<div class="modal-body"><p class="confirmation-copy">Delete <strong>${esc(s.name)}</strong> and its associated tasks?</p></div>`,`<button class="button button-secondary" data-close-modal>Cancel</button><button class="button danger-button" id="confirm-delete-subject">Delete course</button>`);document.getElementById('confirm-delete-subject').addEventListener('click',()=>{state.subjects=state.subjects.filter(x=>x.id!==s.id);state.tasks=state.tasks.filter(t=>t.subject!==s.name);if(subjectDetail===s.name)subjectDetail=null;save();closeModal();render();toast('Course and its assignments deleted.')})})}
function route(){page=location.hash.slice(1)||'overview';if(!pageNames[page]){page='overview';history.replaceState(null,'',location.pathname+location.search+'#overview')}render()}document.addEventListener('click',e=>{const course=e.target.closest('[data-subject]');if(course){e.preventDefault();const found=state.subjects.find(s=>s.id===course.dataset.subject);subjectDetail=found?.name||null;page='subjects';location.hash='subjects';render()}});document.getElementById('global-search').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.value.trim()){taskQuery=e.target.value.trim();if(page==='tasks'){render();document.getElementById('task-search')?.focus()}else location.hash='tasks'}});initializeAuth();

const authModes={login:{title:'Welcome back',copy:'Sign in to pick up where you left off.',submit:'Sign in',busy:'Signing in…'},signup:{title:'Create your account',copy:'A calmer way to keep track of what you need to learn.',submit:'Create account',busy:'Creating account…'},forgot:{title:'Reset your password',copy:'Enter your email and we’ll send you a link to choose a new password.',submit:'Send reset link',busy:'Sending…'},reset:{title:'Choose a new password',copy:'Set a new password to finish resetting your account.',submit:'Save password',busy:'Saving…'},invite:{title:'Accept your invitation',copy:'Choose a password to finish setting up your StudySync account.',submit:'Create password',busy:'Setting up…'}};let inviteToken='';
function showAuth(message='',mode='login'){
 const app=document.querySelector('.app-shell'),screen=document.getElementById('auth-screen'),m=authModes[mode]||authModes.login;document.querySelector('.skip-link').hidden=true;app.hidden=true;screen.hidden=false;
 const nameField=mode==='signup'?'<label for="auth-name">Your name</label><input id="auth-name" name="name" autocomplete="name" maxlength="80" required>':'',emailField=['login','signup','forgot'].includes(mode)?'<label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" required>':'',passwordField=mode==='forgot'?'':`<label for="auth-password">${mode==='reset'||mode==='invite'?'New password':'Password'}</label><input id="auth-password" name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="${mode==='login'?1:8}" required>`;
 const links=mode==='login'?`<p class="auth-switch"><button type="button" data-auth-mode="forgot">Forgot your password?</button></p><p class="auth-switch">New to StudySync? <button type="button" data-auth-mode="signup">Create an account</button></p>`:mode==='signup'||mode==='forgot'?`<p class="auth-switch">${mode==='signup'?'Already have an account?':'Remembered it?'} <button type="button" data-auth-mode="login">Sign in</button></p>`:'';
 screen.innerHTML=`<div class="auth-card"><a class="auth-brand" href="#" aria-label="StudySync"><span class="brand-mark" aria-hidden="true">${icon('book',22)}</span><span>Study<span>Sync</span></span></a><div class="eyebrow">YOUR STUDY SPACE</div><h1>${m.title}</h1><p class="auth-copy">${m.copy}</p><form id="auth-form" data-mode="${mode}"><div class="form-field">${nameField}${emailField}${passwordField}</div><p class="auth-message" id="auth-message" role="status" aria-live="polite">${esc(message)}</p><button class="button button-primary auth-submit" type="submit">${m.submit} ${icon('arrow',16)}</button></form>${links}<p class="auth-note">Your study data is private to your account.</p></div>`;
 screen.querySelectorAll('[data-auth-mode]').forEach(b=>b.addEventListener('click',e=>showAuth('',e.currentTarget.dataset.authMode)));screen.querySelector('#auth-form').addEventListener('submit',submitAuth);
}
function showCheckEmail(email){const screen=document.getElementById('auth-screen');screen.innerHTML=`<div class="auth-card"><a class="auth-brand" href="#" aria-label="StudySync"><span class="brand-mark" aria-hidden="true">${icon('book',22)}</span><span>Study<span>Sync</span></span></a><div class="eyebrow">ALMOST THERE</div><h1>Check your email</h1><p class="auth-copy">We sent a confirmation link to <strong>${esc(email)}</strong>.</p><p class="auth-copy">Open that email and tap the link to confirm your account. You’ll be signed in to StudySync automatically.</p><p class="auth-note">Can’t find it? Check your spam or promotions folder. The link can take a minute or two to arrive.</p></div>`}
function authErrorMessage(error,mode){if(error instanceof MissingIdentityError)return 'Sign-in is not available yet. Netlify Identity is not enabled for this site.';if(error instanceof AuthError){const msg=(error.message||'').toLowerCase();if(msg.includes('not confirmed'))return 'Please confirm your email address first — check your inbox for the confirmation link.';if(error.status===401||error.status===400&&mode==='login')return 'Invalid email or password.';if(error.status===403)return mode==='signup'?'New signups are currently closed. Ask the site owner for an invite.':'That action isn’t allowed.';if(error.status===422)return mode==='signup'&&msg.includes('registered')?'An account with this email already exists. Try signing in.':error.message||'Check your details and try again.';if(error.status===429)return 'Too many attempts. Please wait a moment and try again.'}return error?.message||'Something went wrong. Please try again.'}
async function submitAuth(event){event.preventDefault();const form=event.currentTarget,mode=form.dataset.mode,m=authModes[mode],message=document.getElementById('auth-message'),button=form.querySelector('button[type=submit]'),email=form.elements.email?.value.trim(),password=form.elements.password?.value;button.disabled=true;button.textContent=m.busy;message.textContent='';try{if(mode==='signup'){const user=await signup(email,password,{full_name:form.elements.name.value.trim()});if(!user?.emailVerified){showCheckEmail(email);return}}else if(mode==='login')await login(email,password);else if(mode==='forgot'){await requestPasswordRecovery(email);showAuth('If an account exists for that email, a password reset link is on its way.','login');return}else if(mode==='reset'){await updateUser({password});toast('Your password has been updated.','success')}else if(mode==='invite'){await acceptInvite(inviteToken,password);inviteToken=''}await loadApp()}catch(error){message.textContent=authErrorMessage(error,mode);button.disabled=false;button.innerHTML=`${m.submit} ${icon('arrow',16)}`}}
async function loadApp(){currentUser=await getUser();if(!currentUser){showAuth();return}const response=await dataRequest();if(response.status===401){currentUser=null;showAuth('Your session has expired. Please sign in again.');return}if(!response.ok)throw new Error('Study data is unavailable. Try again shortly.');state=await response.json();document.getElementById('auth-screen').hidden=true;document.querySelector('.skip-link').hidden=false;document.querySelector('.app-shell').hidden=false;if(!window.studySyncBound){bindGlobal();window.studySyncBound=true}route()}
async function initializeAuth(){let callback;try{callback=await handleAuthCallback()}catch(error){showAuth(error instanceof MissingIdentityError?authErrorMessage(error,'login'):'That link is invalid or has expired. Please request a new one.');return}try{if(callback?.type==='invite'){inviteToken=callback.token||'';showAuth('','invite');return}if(callback?.type==='recovery'){showAuth('','reset');return}await loadApp();if(callback?.type==='confirmation')toast('Email confirmed. Welcome to StudySync!','success');if(callback?.type==='email_change')toast('Your email address has been updated.','success')}catch(error){showAuth(authErrorMessage(error,'login'))}}
